    @EventHandler( payloadType=CreateDashboardEvent.class )
    public void handle( CreateDashboardEvent event) {
	    LOGGER.info("handling CreateDashboardEvent - " + event );
	    Dashboard entity = new Dashboard();
            entity.setDashboardId( event.getDashboardId() );
            entity.setTitle( event.getTitle() );
            entity.setTheme( event.getTheme() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDashboard( entity );
    }

