    /**
     * Method to retrieve the Dashboard via an DashboardPrimaryKey.
     * @param 	id Long
     * @return 	Dashboard
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Dashboard handle( FindDashboardQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getDashboardId() );
    }
    
    /**
     * Method to retrieve a collection of all Dashboards
     *
     * @param	query	FindAllDashboardQuery 
     * @return 	List<Dashboard> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Dashboard> handle( FindAllDashboardQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindDashboard,
 * but only if the id matches
 *
 * @param		entity	Dashboard
 */
	protected void emitFindDashboard( Dashboard entity ) {
		LOGGER.info("handling emitFindDashboard" );
		
	    queryUpdateEmitter.emit(FindDashboardQuery.class,
	                            query -> query.getFilter().getDashboardId().equals(entity.getDashboardId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDashboard
	 * 
	 * @param		entity	Dashboard
	 */
	protected void emitFindAllDashboard( Dashboard entity ) {
		LOGGER.info("handling emitFindAllDashboard" );
		
	    queryUpdateEmitter.emit(FindAllDashboardQuery.class,
	                            query -> true,
	                            entity);
	}

